/**
 * CANONICAL JSON: one byte string per value, so a signature or an AEAD's associated data means exactly one thing.
 * Keys sorted by UTF-16 code unit (JavaScript's default sort, as RFC 8785 does), no whitespace, and the value space
 * cut to what the protocol uses: strings, booleans, null, arrays, plain objects and SAFE INTEGERS. A float has no
 * single shortest form across platforms, so the protocol has none (times are integer milliseconds, sizes integer
 * bytes). `undefined` is refused rather than dropped: a dropped key would sign a different object than was meant.
 */

export function canonicalJson(value         )         {
  if (value === null) return "null";
  switch (typeof value) {
    case "string":
      // Lone surrogates are refused here too, so the string has a UTF-8 form.
      utf8Encode(value);
      return JSON.stringify(value);
    case "boolean":
      return value ? "true" : "false";
    case "number":
      if (!Number.isSafeInteger(value)) throw new TypeError("canonical JSON carries safe integers only");
      return Object.is(value, -0) ? "0" : String(value);
    case "object": {
      if (Array.isArray(value)) return `[${value.map(canonicalJson).join(",")}]`;
      const proto = Object.getPrototypeOf(value);
      if (proto !== Object.prototype && proto !== null) throw new TypeError("canonical JSON carries plain objects only");
      const record = value                           ;
      const keys = Object.keys(record).sort();
      return `{${keys.map((k) => `${JSON.stringify(k)}:${canonicalJson(record[k])}`).join(",")}}`;
    }
    default:
      throw new TypeError(`canonical JSON cannot carry ${typeof value}`);
  }
}

export const canonicalBytes = (value         )             => utf8Encode(canonicalJson(value));

/** Parses JSON and gives null instead of throwing. Duplicate keys are not detectable through JSON.parse; the
 * schemas' exact-key rule plus canonical re-encoding (signatures are over canonical bytes) make them harmless. */
export function parseJson(text        )          {
  try {
    return JSON.parse(text)           ;
  } catch {
    return undefined;
  }
}

