export const systemRandom = (length) => new Uint8Array(randomBytes(length));

export const KEY_BYTES = 32;
export const SIGNATURE_BYTES = 64;
export const NONCE_BYTES = 24;
export const TAG_BYTES = 16;

const DER = {
  ed25519: { pkcs8: Buffer.from("302e020100300506032b657004220420", "hex"), spki: Buffer.from("302a300506032b6570032100", "hex") },
  x25519: { pkcs8: Buffer.from("302e020100300506032b656e04220420", "hex"), spki: Buffer.from("302a300506032b656e032100", "hex") },
};
const u8 = (bytes) => new Uint8Array(bytes);
const privateKeyOf = (kind, seed) => createPrivateKey({ key: Buffer.concat([DER[kind].pkcs8, Buffer.from(seed)]), format: "der", type: "pkcs8" });
const publicKeyOf = (kind, raw) => createPublicKey({ key: Buffer.concat([DER[kind].spki, Buffer.from(raw)]), format: "der", type: "spki" });
const rawPublic = (kind, seed) => u8(createPublicKey(privateKeyOf(kind, seed)).export({ format: "der", type: "spki" }).subarray(DER[kind].spki.length));

export const sha256 = (data) => u8(createHash("sha256").update(data).digest());

export const hkdfSha256 = (ikm, salt, info, length) => u8(Buffer.from(hkdfSync("sha256", ikm, salt, info, length)));

export const ed25519PublicKey = (secret) => rawPublic("ed25519", secret);
export const x25519PublicKey = (secret) => rawPublic("x25519", secret);

export const ed25519Sign = (message, secret) => u8(nodeSign(null, message, privateKeyOf("ed25519", secret)));

/** Never throws: a malformed key or signature is simply not a valid signature. */
export function ed25519Verify(signature, message, publicKey) {
  if (signature.length !== SIGNATURE_BYTES || publicKey.length !== KEY_BYTES) return false;
  try {
    return nodeVerify(null, message, publicKeyOf("ed25519", publicKey), signature);
  } catch {
    return false;
  }
}

/** X25519, or null for the all-zero shared secret (a low-order public key), which must never become a key. */
export function x25519Shared(secret, publicKey) {
  if (publicKey.length !== KEY_BYTES) return null;
  try {
    const shared = u8(diffieHellman({ privateKey: privateKeyOf("x25519", secret), publicKey: publicKeyOf("x25519", publicKey) }));
    return shared.every((b) => b === 0) ? null : shared;
  } catch {
    return null;
  }
}

/** HChaCha20 (draft-irtf-cfrg-xchacha section 2.2) from one chacha20 block: words 0..3 and 12..15 before the final addition. */
function hchacha20(key, nonce16) {
  const block = createCipheriv("chacha20", Buffer.from(key), Buffer.from(nonce16)).update(Buffer.alloc(64));
  const input = Buffer.from(nonce16);
  const sigma = [0x61707865, 0x3320646e, 0x79622d32, 0x6b206574];
  const out = Buffer.alloc(32);
  for (let i = 0; i < 4; i += 1) out.writeUInt32LE((block.readUInt32LE(i * 4) - sigma[i]) >>> 0, i * 4);
  for (let i = 0; i < 4; i += 1) out.writeUInt32LE((block.readUInt32LE(48 + i * 4) - input.readUInt32LE(i * 4)) >>> 0, 16 + i * 4);
  return out;
}
const ietfNonce = (nonce24) => Buffer.concat([Buffer.alloc(4), Buffer.from(nonce24).subarray(16, 24)]);

export function aeadSeal(key, nonce, aad, plaintext) {
  const cipher = createCipheriv("chacha20-poly1305", hchacha20(key, nonce.subarray(0, 16)), ietfNonce(nonce), { authTagLength: TAG_BYTES });
  cipher.setAAD(Buffer.from(aad), { plaintextLength: plaintext.length });
  return u8(Buffer.concat([cipher.update(Buffer.from(plaintext)), cipher.final(), cipher.getAuthTag()]));
}

/** Null when the tag does not verify: wrong key, a changed byte, or changed associated data. */
export function aeadOpen(key, nonce, aad, ciphertext) {
  if (nonce.length !== NONCE_BYTES || ciphertext.length < TAG_BYTES) return null;
  try {
    const body = Buffer.from(ciphertext.subarray(0, ciphertext.length - TAG_BYTES));
    const decipher = createDecipheriv("chacha20-poly1305", hchacha20(key, nonce.subarray(0, 16)), ietfNonce(nonce), { authTagLength: TAG_BYTES });
    decipher.setAAD(Buffer.from(aad), { plaintextLength: body.length });
    decipher.setAuthTag(Buffer.from(ciphertext.subarray(ciphertext.length - TAG_BYTES)));
    return u8(Buffer.concat([decipher.update(body), decipher.final()]));
  } catch {
    return null;
  }
}

// ---- packages/remote-protocol/src/ids.ts
/**
 * OPAQUE IDS. Every id the relay sees is a prefix and 16 random bytes in base64url, nothing else: a project id is
 * never a folder name, a session id never a title. The prefix says what kind of thing it names, so an id of one kind
 * cannot be passed where another is meant. A computer that needs a STABLE id for a folder derives one (an HMAC of the
 * path under a key that never leaves the computer, cut to 16 bytes); the relay still sees only noise.
 */

export const ID_PREFIXES = {
  cmd: "a command",
  idk: "an idempotency key",
  ses: "an agent session",
  dev: "a device (one phone install or one computer)",
  prj: "a project folder on a computer",
  chn: "an end-to-end channel between one phone and one computer",
  apr: "an approval request",
  qst: "a question from an agent",
  stp: "a step of an agent run",
  pli: "an item of an agent's own plan (its to-do list), stable across the plan's versions",
  sag: "a subagent an agent started, for the agent map",
  rot: "a root folder on a computer where a phone may create new project folders (worktrust remote roots add)",
  att: "a file sent from the phone into a session's project inbox (transfer.ts)",
  pvw: "one local preview render (transfer.ts)",
  rel: "a release on a computer: a bundle of tasks in one project (release.ts)",
  tsk: "a task of a release, run as one remote session",
  plr: "one run of a release's pipeline on the computer (pipeline.ts)",
  usr: "an account, as the remote system knows it (never the Passport owner id)",
  jti: "a token's single-use id",
}         ;

const ID_BYTES = 16;
const ID_BODY = /^[A-Za-z0-9_-]{22}$/;

export function mintId(prefix          , random        )         {
  return `${prefix}_${toBase64Url(random(ID_BYTES))}`;
}

export function isOpaqueId(value         , prefix          )                  {
  if (typeof value !== "string" || !value.startsWith(`${prefix}_`)) return false;
  const body = value.slice(prefix.length + 1);
  return ID_BODY.test(body) && fromBase64Url(body)?.length === ID_BYTES;
}

