/**
 * ONE SPEC, THREE USES. A schema here is plain data: the validator walks it, `Infer` turns it into the TypeScript
 * type (so the type and the runtime check cannot drift), and scripts/check-remote-protocol.mjs reads it to prove
 * that nothing the relay can see is able to carry content. Hand-written type guards, no zod: the repo standardises
 * on none, and a schema the checker can introspect is worth more here than a library's ergonomics.
 *
 * `text` is the one CONTENT kind: a prompt, a step label, a file name, output. It may appear only inside a sealed
 * body. Every other kind is bounded so that it cannot smuggle a sentence: ids are prefixed random strings, enums
 * are closed lists, integers are integers.
 */

/** The relay-visible box a sealed body travels in (see crypto/channel.ts). */

export const text = (max        , min = 0) => ({ t: "text", min, max })         ;
export const token = (max = 4096) => ({ t: "token", max })         ;
export const id =                           (prefix   ) => ({ t: "id", prefix })         ;
export const oneOf =                                    (values   ) => ({ t: "enum", values })         ;
export const int = (min        , max         = Number.MAX_SAFE_INTEGER) => ({ t: "int", min, max })         ;
export const bool = () => ({ t: "bool" })         ;
export const b64 = (bytes                                  ) => ({ t: "b64", ...bytes })         ;
export const sealed = () => ({ t: "sealed" })         ;
export const nullable =                       (of   ) => ({ t: "nullable", of })         ;
export const optional =                       (of   ) => ({ t: "optional", of })         ;
export const list =                       (of   , max        , min = 0) => ({ t: "list", of, min, max })         ;
