        project_id: nullable(id("prj")),
        adapter: oneOf(ADAPTER_IDS),
        origin: oneOf(SESSION_ORIGINS),
        attention: ATTENTION_SPEC,
        title: nullable(label(200)),
        /** The project tree (2026-11-07): the session's name, agent model, state and last event time, and its release task. */
        name: optional(nullable(label(100))),
        model: optional(nullable(label(128))),
        state: optional(oneOf(SESSION_LIST_STATES)),
        last_activity_at: optional(nullable(int(0))),
        release_id: optional(nullable(id("rel"))),
        task_id: optional(nullable(id("tsk"))),
        /** Background jobs its agent reports still running (2026-11-08: "ready, but a job is still running"); absent when it cannot tell. */
        background_jobs: optional(int(0, 99)),
        /** `terminal` for a terminal session (release 19); absent means structured. */
        mode: optional(oneOf(ADAPTER_MODES)),
